.vn-xi { font: 400 11px var(--mono); fill: rgb(244 241 232 / .6); }
.vn-a, .vn-b { fill: none; stroke-width: 1.8; }
.vn-a { stroke: #6fa8dc; } .vn-b { stroke: #e8862c; }
.vn-l { font: 700 14px var(--mono); text-anchor: middle; }
.vn-a-l { fill: #6fa8dc; } .vn-b-l { fill: #e8862c; }
.vn-tint { fill: rgb(240 180 95 / .16); }
.vn-h { fill: none; stroke: #f0b45f; stroke-width: 1.3; opacity: .8;
        animation: vn-hatch 1.6s linear infinite; }
@keyframes vn-hatch { to { transform: translateX(6px); } }
.vn-ga { animation: vn-ca 10s ease-in-out infinite; }
