@keyframes vn-ca { 0% { opacity: 0; transform: translateX(-16px); } 9%, 90% { opacity: 1; transform: none; } 100% { opacity: 0; transform: translateX(-16px); } }
@keyframes vn-cb { 0% { opacity: 0; transform: translateX(16px); } 9%, 90% { opacity: 1; transform: none; } 100% { opacity: 0; transform: translateX(16px); } }
.vn-say { display: grid; margin-top: .7rem; font: 700 1.3rem var(--mono); color: var(--paper);
          text-align: center; }
.vn-s { grid-area: 1 / 1; }
.vn-say b.vn-ta { color: #6fa8dc; } .vn-say b.vn-tb { color: #e8862c; }
.vn-r:not(.vn-r-and), .vn-s:not(.vn-s-and) { opacity: 0; }
.vn-r-and { animation: vn-and 10s ease-in-out infinite; }
@keyframes vn-and { 0%, 8% { opacity: 0; } 13%, 32% { opacity: 1; } 37%, 100% { opacity: 0; } }
.vn-s-and { animation: vn-s-and 10s ease-in-out infinite; }
