.or-p { transform-origin: 60px 60px; animation: or-turn var(--t) linear infinite; }
.or-ring { transform-origin: var(--o); animation: or-back 117.81s linear infinite; }
.or-ring path { fill: none; stroke: #e6c98a; stroke-width: .7; opacity: .8; }
@keyframes or-turn { to { transform: rotate(-360deg); } }
@keyframes or-back { to { transform: rotate(360deg); } }
@media (prefers-reduced-motion: reduce) {
